import{_ as i,C as r,o as t,c as s,a5 as a,E as n}from"./chunks/framework.BwlBv862.js";const g=JSON.parse('{"title":"Diagnostique uma operação com falha","description":"","frontmatter":{"title":"Diagnostique uma operação com falha","docId":"user.preferences.troubleshooting","translationKey":"user.preferences.troubleshooting","locale":"pt","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"40d8c5706363baa28e4114397696c8c2adb320843271a00efb3772be0322d5e2","translationRevision":"6b2ce018f93c305fc9204edda65de23bf2110b649a88ce164ae7aaed5d0b7d76","order":30},"headers":[],"relativePath":"pt/user/preferences/troubleshooting.md","filePath":"pt/user/preferences/troubleshooting.md","lastUpdated":1794611623000}'),d={name:"pt/user/preferences/troubleshooting.md"};function l(c,e,u,p,m,h){const o=r("DemoFrame");return t(),s("div",null,[e[0]||(e[0]=a('<h1 id="diagnose-a-failed-operation" tabindex="-1">Diagnostique uma operação com falha <a class="header-anchor" href="#diagnose-a-failed-operation" aria-label="Permalink to &quot;Diagnostique uma operação com falha {#diagnose-a-failed-operation}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Identifique o componente com falha e colete um relatório útil sem disparar efeitos repetidamente. Você precisa da versão do aplicativo, do horário aproximado da falha e da operação tentada. Mantenha um <a href="./backups.html">backup</a> antes de redefinir ou substituir dados.</p><h2 id="inspect-the-nearest-evidence" tabindex="-1">Inspecione a evidência mais próxima <a class="header-anchor" href="#inspect-the-nearest-evidence" aria-label="Permalink to &quot;Inspecione a evidência mais próxima {#inspect-the-nearest-evidence}&quot;">​</a></h2><ol><li>Leia o erro na área onde a falha ocorreu. Use sua ação de status de diagnóstico ou abra <strong>Diagnostics</strong> para inspecionar entradas relacionadas.</li><li>Filtre por origem, nível ou texto. Origens úteis incluem LIVE, monitoramento, plugins, conta, sincronização, atualizações, transporte, catálogo, instalação e colaboração.</li><li>Selecione a entrada relevante e guarde horário, código, identificadores de solicitação/entidade e descrição curta. Expanda os detalhes quando disponíveis.</li><li>Copie os diagnósticos filtrados ou exporte o relatório de texto. Se a cópia/exportação falhar, use o texto alternativo exibido. Revise antes de compartilhar; remova tokens privados, cookies, links de convite e conteúdo pessoal.</li><li>Inclua uma reprodução curta: página, criador/perfil/plugin selecionado, ação realizada, resultado esperado e resultado real. Explique se aconteceu antes ou depois de uma atualização.</li></ol><h2 id="isolate-common-failures" tabindex="-1">Isole falhas comuns <a class="header-anchor" href="#isolate-common-failures" aria-label="Permalink to &quot;Isole falhas comuns {#isolate-common-failures}&quot;">​</a></h2><p>Para um feed vazio, limpe pesquisa e filtros, retome a rolagem e confirme a <a href="./../live/connections.html">conexão</a>. Rolagem pausada não é desconexão. Um indicador de perda de exibição não comprova que pontos ou análises perderam o mesmo evento.</p><p>Para uma automação sem execução, verifique perfil ativo, ativação de evento/ação, acionador, caminhos de campos dos filtros e intervalo de espera. Inspecione o histórico antes de alterar efeitos. <strong>Test</strong> pode executar ações de áudio, HTTP, pontos e plugins.</p><p>Para uma falha de plugin, leia o erro da tarefa de instalação ou conexão. Para o Cloud, confira o estado da conta e a área afetada em vez de substituir um cookie do TikTok. Para overlays, inspecione o status do gateway e a configuração da fonte. Para atualizações, use as <a href="./../updates.html">instruções de atualização manual</a> quando a instalação estiver indisponível.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado e status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado e status {#expected-result-and-status}&quot;">​</a></h2><p>Filtragem, cópia e exportação de texto de diagnósticos estão disponíveis. Um aplicativo empacotado também precisa dos recursos web e do ambiente de execução da plataforma. No Linux, confira o ambiente GTK/WebKitGTK compatível e a sessão X11/XWayland; no Windows, confira o WebView2. Consulte <a href="./../requirements.html">requisitos</a> para o escopo de instalação.</p><h2 id="recovery" tabindex="-1">Recuperação <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperação {#recovery}&quot;">​</a></h2><p>Tente novamente após corrigir a causa específica. Para conflitos de revisão, recarregue e revise o estado salvo atual. Para um comando remoto não confirmado, inspecione seu diário/status antes de enviar outro: um tempo limite pode ocorrer após um efeito bem-sucedido. Se a inicialização falhar, informe pacote/versão e registro de inicialização em vez de excluir o diretório de dados.</p>',13)),n(o,{scenario:"diagnostics",locale:"pt",tour:"diagnostics",title:"Demonstração: diagnósticos"}),e[1]||(e[1]=a('<h2 id="operational-details" tabindex="-1">Detalhes de operação <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalhes de operação {#operational-details}&quot;">​</a></h2><p>Diagnostics é um registro da interface em memória, limitado a 2.000 entradas ou 2 MiB. Agrupa repetições em cinco segundos. Mostra inicialmente 100; exportar inclui todas as entradas filtradas, enquanto <strong>Limpar</strong> apaga o registro inteiro. Copie/exporte antes de fechar, reiniciar, limpar ou trocar/sair de uma conta Cloud conhecida: essas mudanças esvaziam o histórico.</p><p>Sem janela, procure o <code>tiktools.log</code> nativo (<code>controller.log</code> no modo controlador) em <code>%LOCALAPPDATA%/TikTools/logs</code> no Windows ou <code>${XDG_DATA_HOME:-~/.local/share}/TikTools/logs</code> no Linux. <code>TIKTOOLS_HOME</code> altera a raiz e <code>TIKTOOLS_LOG_DIR</code> substitui o diretório dos logs. Se o próprio registro falhar, o arquivo pode não existir; preserve o erro de terminal/inicialização disponível. Logs nativos não garantem a redação da interface: revise tudo antes de compartilhar.</p>',3))])}const v=i(d,[["render",l]]);export{g as __pageData,v as default};
